   "id": "z254add72",
   "sez": "mondo",
   "titolo": "La Germania processa un ucraino accusato di aver fatto saltare i gasdotti Nord Stream",
   "orig": "Germany puts Ukrainian on trial accused of blowing up Nord Stream pipelines",
   "lead": "A quattro anni dagli attacchi che danneggiarono i gasdotti Nord Stream, un cittadino ucraino identificato come Serhii K. comparirà davanti a un tribunale tedesco con l'accusa di aver partecipato a un piano per distruggere le infrastrutture che trasportavano gas russo verso la Germania. Il processo riaccende l'attenzione su uno degli episodi di sabotaggio più controversi legati alla guerra in Ucraina, che ha colpito direttamente le forniture energetiche europee. Lo riferisce BBC News.",
   "more": [
    "I gasdotti Nord Stream collegavano la Russia alla Germania sotto il Mar Baltico, trasportando gas naturale russo in Europa; furono danneggiati da esplosioni nel settembre 2022, episodio mai chiarito ufficialmente e attribuito da più inchieste a un sabotaggio."
   ],
