   "id": "z33c7d8ae",
   "sez": "mondo",
   "titolo": "La corte federale australiana annulla l'ordine di protezione di Plibersek che bloccava una miniera d'oro",
   "orig": "Court overturns Tanya Plibersek’s protection order which stalled controversial NSW goldmine",
   "lead": "La corte federale australiana ha annullato un raro ordine di protezione emesso dall'ex ministra dell'Ambiente Tanya Plibersek in base alla legge sul patrimonio indigeno, che secondo l'azienda Regis Resources bloccava di fatto lo sviluppo della miniera d'oro McPhillamys a Blayney, nel New South Wales centro-occidentale. Regis Resources aveva impugnato la decisione del 2024, presa ai sensi della sezione 10 dell'Aboriginal and Torres Strait Islander Heritage Protection Act. Lo riferisce The Guardian.",
   "more": [
    "L'Aboriginal and Torres Strait Islander Heritage Protection Act è una legge australiana che consente al governo di proteggere siti di significato culturale per le popolazioni indigene, anche bloccando progetti industriali ritenuti dannosi per tali luoghi."
   ],
