   "id": "zb69d6758",
   "sez": "mondo",
   "titolo": "In Iran si acuiscono le tensioni politiche mentre la guerra aggrava la crisi economica",
   "orig": "Iran: Political infighting deepens as economic woes mount during war",
   "lead": "In Iran le divisioni politiche interne si stanno intensificando mentre il Paese affronta una crisi economica aggravata dal conflitto in corso. Le fazioni più intransigenti stanno aumentando la pressione sul governo, chiedendo la rimozione del ministro degli Esteri Abbas Araghchi. Il ministro del Petrolio si è dimesso, ma le dimissioni non sembrano alleviare la pressione politica sul presidente Masoud Pezeshkian, alle prese con un contesto interno sempre più instabile. Lo riferisce Deutsche Welle.",
   "more": [
    "Masoud Pezeshkian è l'attuale presidente iraniano, considerato esponente dell'area più moderata rispetto alle fazioni conservatrici e hardliner che controllano gran parte delle istituzioni del Paese, incluse le forze di sicurezza e la guida suprema."
   ],
