   "id": "z4c8ec842",
   "sez": "sport",
   "titolo": "Peralta brilla e i Rays sfruttano l'errore di Ramírez per pareggiare l'ALCS contro i Guardians",
   "orig": "Peralta shines as Rays seize on Ramírez error to level ALCS against Guardians",
   "lead": "Freddy Peralta ha lanciato sei riprese senza concedere punti e i Tampa Bay Rays hanno battuto i Cleveland Guardians 3-1, pareggiando la serie di campionato dell'American League (ALCS) sull'1-1. Un errore difensivo di José Ramírez ha aperto la strada a un quarto inning da tre punti per i Rays. La serie si sposta ora a Cleveland per gara 3, in programma giovedì sera.",
   "more": [
    "L'ALCS è la serie che assegna il titolo della American League nel baseball professionistico statunitense, tappa decisiva verso le World Series; si gioca al meglio di sette partite tra le due migliori squadre della stagione regolare e dei playoff."
   ],
