   "id": "z525053a9",
   "sez": "spazio",
   "titolo": "Marte attraversa l'ammasso del Presepe sotto un'aurora boreale",
   "orig": "APOD: 2026 October 14 – Mars and the Beehive Under an Aurora",
   "lead": "Un'immagine astronomica del giorno pubblicata dalla NASA mostra Marte che si unisce all'ammasso stellare del Presepe (Beehive), sotto una tenda aurorale e sopra l'orizzonte innevato vicino a Lansjärv, in Svezia. Il fenomeno, descritto come una «coincidenza cosmica», unisce in un solo scatto il pianeta rosso, l'ammasso catalogato come Messier 44 nella costellazione del Cancro, e un'aurora boreale visibile nel cielo nordico.",
   "more": [
    "L'ammasso del Presepe, o Beehive, è un gruppo di stelle visibile a occhio nudo nella costellazione del Cancro, noto fin dall'antichità per il suo aspetto nebuloso; Marte, il pianeta rosso, compie periodicamente passaggi apparenti vicino a questo ammasso nel cielo notturno."
   ],
