   "id": "z8ab5ba38",
   "sez": "economia",
   "titolo": "I giovani malesi spendono 1,3 miliardi di dollari in credito a breve termine, allarme per i debiti insoluti",
   "orig": "Young Malaysians’ US$1.3bn short-term credit spree sparks warning over bad debt",
   "lead": "Il ministero delle Finanze della Malaysia ha rivelato che i cittadini sotto i 30 anni hanno acquistato beni e servizi per circa 5,4 miliardi di ringgit (1,32 miliardi di dollari) tramite formule di credito a breve termine nella prima metà dell'anno. Il ministero ha registrato 65,9 milioni di acquisti «buy now, pay later» tra i giovani consumatori nei primi sei mesi del 2026, pari a oltre un terzo del totale degli acquisti nazionali. Al 30 giugno il saldo di finanziamenti BNPL in essere tra questa fascia era elevato. Lo riferisce South China Morning Post.",
   "more": [
    "Il «buy now, pay later» (BNPL) è una formula di credito al consumo che permette di acquistare beni pagandoli a rate senza interessi immediati, molto diffusa tra i giovani ma soggetta a critiche per il rischio di indebitamento eccessivo e difficoltà di rimborso."
   ],
