   "id": "z25136dbd",
   "sez": "spazio",
   "titolo": "Le ipernove potrebbero essere solo ipotesi senza prove solide",
   "orig": "Hypernovae May Be All Hype, No Nova",
   "lead": "Gli astrofisici ritengono da tempo che le ipernove siano le esplosioni stellari più potenti dell'universo, il tipo più esplosivo di supernova a collasso del nucleo. Una nuova ricerca mette però in dubbio l'esistenza stessa di questi fenomeni, sottolineando che le prove a loro sostegno non sono abbondanti e che nuovi studi individuano lacune significative nelle evidenze finora raccolte. Lo riferisce Universe Today.",
   "more": [
    "Le supernove a collasso del nucleo sono esplosioni che segnano la morte di stelle molto massicce, quando il nucleo collassa su sé stesso; le ipernove sarebbero una categoria ancora più energetica di queste esplosioni, ipotizzata ma non confermata con certezza dagli osservatori."
   ],
