   "titolo": "A Roma il bread pairing trasforma il pane in protagonista della degustazione",
   "orig": "Bread pairing, ad ogni piatto il suo pane e la scarpetta regna",
   "lead": "A Roma si diffonde il «bread pairing», pratica che abbina un pane specifico a ogni piatto, rendendo il pane parte integrante dell'esperienza gastronomica anziché semplice accompagnamento. Il pane, spiega ANSA, non si limita più a fare da contorno ma diventa elemento studiato della degustazione, mentre la tradizionale «scarpetta» per raccogliere il sugo rimane un gesto molto apprezzato dai commensali. Lo riferisce ANSA.",
   "more": [
    "Il «bread pairing» è una pratica gastronomica che consiste nello scegliere tipi diversi di pane da abbinare a specifici piatti, valorizzandone sapori e consistenze, in modo simile all'abbinamento tra cibo e vino nella ristorazione di livello."
   ],
