   "sez": "cucina",
   "titolo": "Polpettone di verdure senza sprechi con il cavolfiore",
   "orig": "Polpettone di verdure, la ricetta senza sprechi con il cavolfiore",
   "lead": "La Cucina Italiana propone una ricetta di polpettone di cavolfiore pensata per non sprecare nessuna parte dell'ortaggio: le cimette vengono usate per l'impasto, mentre foglie e coste servono a preparare una salsa di accompagnamento. La ricetta punta a valorizzare un ingrediente spesso utilizzato solo parzialmente in cucina, trasformandolo in un piatto completo a base vegetale.",
   "more": [
    "Il cavolfiore è un ortaggio della famiglia delle crucifere, di cui tradizionalmente si consumano solo le cimette, mentre foglie e coste vengono spesso scartate pur essendo commestibili e utilizzabili in preparazioni come salse o minestre."
   ],
