   "sez": "adolescenti",
   "titolo": "Scuola, ANIEF rilancia le richieste su settimana corta, buoni pasto e stipendi per il rinnovo del contratto",
   "orig": "Scuola, settimana lavorativa di cinque giorni, buoni pasto e stipendi. Pacifico (ANIEF) rilancia le richieste per il rinnovo del contratto",
   "lead": "Marcello Pacifico, presidente del sindacato ANIEF, ha rilanciato le richieste del sindacato per il rinnovo del contratto del personale scolastico, chiedendo la settimana lavorativa di cinque giorni per docenti e personale ATA, il riconoscimento dei buoni pasto e la revisione dei vincoli sulla mobilità. Pacifico chiede inoltre maggiori risorse per gli stipendi, il riconoscimento del burnout tra il personale e la parità di trattamento tra precari e lavoratori di ruolo, oltre a nuovi investimenti nell'istruzione. Lo riferisce Orizzonte Scuola.",
   "more": [
    "ANIEF è un sindacato italiano della scuola che rappresenta in particolare il personale precario, impegnato su temi come stabilizzazione, condizioni di lavoro e rinnovo dei contratti collettivi del comparto istruzione."
   ],
