   "orig": "Lam Tin MTR station service suspended during peak hours on 2 consecutive days due to equipment malfunction",
   "lead": "La società MTR Corporation ha sospeso il servizio nella stazione di Lam Tin a Hong Kong durante le ore di punta per due giorni consecutivi, a causa di guasti alle apparecchiature. Uno dei malfunzionamenti ha anche provocato un piccolo incendio vicino ai binari. Il servizio è stato interrotto per quasi due ore mercoledì mattina dopo che il personale ha notato del fumo, prima di essere ripristinato intorno alle 10. Lo riferisce Hong Kong Free Press.",
