   "lead": "Le forze del campo largo italiano presentano una posizione comune su economia e contrarietà al riarmo, ma restano divise sul sostegno militare a Kiev: oggi sono previste risoluzioni parlamentari separate. Il Movimento 5 Stelle sostiene nella propria bozza che «le armi allontanano la pace», mentre il Partito Democratico chiede nel suo testo un «sostegno militare per l'autodifesa» dell'Ucraina.",
