   "lead": "Livelli di inquinamento atmosferico dannosi per la salute persistono in diverse zone di Hong Kong mercoledì, dopo che il Dipartimento per la Protezione dell'Ambiente aveva registrato martedì un livello di rischio sanitario definito «grave» nelle stazioni di monitoraggio. L'Osservatorio ha annunciato che una nuova corrente d'aria orientale raggiungerà la costa del Guangdong mercoledì, contribuendo a disperdere lo smog grazie ai venti. Lo riferisce Hong Kong Free Press.",
