   "lead": "Un alto economista della Reserve Bank of Malawi avverte che il Paese non può più contare sulla domanda estera o sul sostegno dei donatori mentre l'economia globale rallenta, sottolineando che il Malawi sta sottoperformando anche rispetto agli standard regionali e deve accelerare le riforme per rafforzare la propria resilienza economica.",
