   "lead": "Adéwálé Àjàdí, autore dell'articolo, sostiene che il fondamento di ogni sistema è il modello mentale che lo sostiene, e che il progetto Afrilition pone le basi per trasformare il futuro del continente africano. L'autore osserva che il mondo africano opera attualmente in reazione al sistema globale esistente, accettandone in larga parte il modello mentale radicato nella storia. Lo riferisce Premium Times.",
