   "titolo": "Il dj Dom Dolla lancia l'etichetta Good Fortune Records",
   "orig": "Dom Dolla Launches Good Fortune Records",
   "lead": "Il superstar dj e produttore australiano Dom Dolla ha annunciato il lancio di Good Fortune Records, una nuova etichetta discografica che debutterà ufficialmente venerdì 16 ottobre con la sua prima uscita, il brano «DANCE» firmato da Torren Foot e rhys from the sticks. L'iniziativa segna un nuovo capitolo nella carriera dell'artista, già affermato nella scena dance internazionale, che con questo progetto punta a offrire una piattaforma a nuovi talenti del genere elettronico. Lo riferisce Billboard.",
   "more": [
    "Dom Dolla è un dj e produttore australiano affermatosi nella scena house ed elettronica internazionale, noto per brani di successo nei club e nelle classifiche dance globali."
   ],
