   "sez": "manga",
   "titolo": "Concluso dopo cinque anni il manga «Kimi to Koete Koi ni Naru»",
   "orig": "Manga 'Kimi to Koete Koi ni Naru' Ends Serialization",
   "lead": "Il manga «Kimi to Koete Koi ni Naru» di Chihiro Yuzuki ha concluso la propria serializzazione mercoledì, con il 133esimo capitolo che chiude un percorso editoriale durato cinque anni. L'opera, un romanzo soprannaturale abbreviato come «Kimikoe», era iniziata nel maggio 2021 sul servizio Manga Mee. Shueisha ha pubblicato il dodicesimo volume il 26 settembre, e il tredicesimo sarà l'ultimo. La serie ha venduto complessivamente 1,8 milioni di copie dei suoi volumi, mentre Yen Press ne cura la pubblicazione in lingua inglese. Lo riferisce MyAnimeList News.",
   "more": [
    "Manga Mee è un servizio di pubblicazione digitale di fumetti giapponesi gestito da Shueisha, una delle maggiori case editrici del settore; i manga romantici soprannaturali uniscono spesso elementi fantastici a storie d'amore seriali."
   ],
