   "titolo": "Apre a Londra la fiera 1-54 di arte contemporanea africana",
   "orig": "1-54 Contemporary African Art Fair opens in London this week – here’s what we’re looking forward to",
   "lead": "La fiera 1-54 Contemporary African Art Fair apre questa settimana a Londra, presso Somerset House, dal 15 al 18 ottobre 2026. L'evento mette in luce artisti contemporanei provenienti dall'Africa e dalla sua diaspora, offrendo una vetrina internazionale a creatori spesso poco rappresentati nei circuiti artistici tradizionali. Lo riferisce Wallpaper*.",
   "more": [
    "Somerset House è uno storico edificio neoclassico nel centro di Londra, oggi sede di mostre ed eventi culturali; la fiera 1-54 è dedicata specificamente alla promozione dell'arte contemporanea africana e della sua diaspora sulla scena internazionale."
   ],
