   "titolo": "Il fantino Andrea Atzeni punta a proseguire il buon avvio di stagione a Happy Valley",
   "orig": "Andrea Atzeni looking to continue early-season momentum with several Happy Valley chances",
   "lead": "Il fantino sardo Andrea Atzeni cerca di dare continuità al suo positivo inizio di stagione con le monte di Wukong Jewellery, Californiatotality e Red Brick Warrior nella riunione di mercoledì sera all'ippodromo di Happy Valley, a Hong Kong. Atzeni ha già ottenuto sette vittorie su 84 corse disputate finora, lo stesso numero di montate del campione in carica Zac Purton, e si è detto grato per il sostegno ricevuto mentre punta a consolidare il suo record personale di 63 vittorie ottenuto la scorsa stagione. Lo riferisce il South China Morning Post.",
   "more": [
    "Happy Valley è uno storico ippodromo di Hong Kong, tra i centri più importanti del mondo per le corse ippiche, dove si disputano regolarmente riunioni serali seguite da un vasto pubblico locale e internazionale."
   ],
