   "sez": "viaggi",
   "titolo": "A Ginza torna il fenomeno dei turisti stranieri seduti sui marciapiedi, nuovo attrito culturale a Tokyo",
   "orig": "Foreign travelers sitting on sidewalks of Tokyo’s Ginza are Japan’s latest tourism culture clash",
   "lead": "Nel quartiere di Ginza, a Tokyo, si ripresenta il fenomeno dei turisti stranieri che si siedono sui marciapiedi, pratica già nota in Giappone con il termine «jibetarian». In vista delle celebrazioni di Halloween, il quartiere di Shibuya ha avviato una campagna di sensibilizzazione pubblica con avvisi multilingue che ricordano il divieto di bere alcolici e gettare rifiuti per strada. Shibuya non è l'unica zona di Tokyo dove si registra attrito culturale tra turisti stranieri e residenti giapponesi. Lo riferisce SoraNews24.",
   "more": [
    "«Jibetarian» è un termine giapponese usato per descrivere chi si siede direttamente a terra o sui marciapiedi in pubblico, comportamento considerato poco rispettoso delle norme sociali locali; Shibuya e Ginza sono quartieri centrali di Tokyo molto frequentati da turisti internazionali."
   ],
