   "id": "z24689878",
   "sez": "prima",
   "titolo": "Dipendente saudita di OpenAI arrestato: aveva nascosto una microspia negli uffici dell'azienda",
   "orig": "Saudi man charged with planting 'sophisticated' recording device in OpenAI office",
   "lead": "Un cittadino saudita dipendente di OpenAI, l'azienda che sviluppa ChatGPT, è stato arrestato il 9 ottobre e incriminato a San Francisco per aver installato un dispositivo di registrazione «sofisticato» negli uffici dell'azienda. Secondo l'accusa, il congegno era avvolto in carta igienica e nascosto in una porta USB sul retro di un televisore, in una sala conferenze riservata ai dirigenti. Le autorità indagano sulle finalità dell'uomo; non ci sono per ora indicazioni che abbia avuto accesso a codici sorgente o dati riservati dell'azienda.",
   "more": [
    "Il caso arriva mentre le aziende di intelligenza artificiale, bersaglio crescente di spionaggio industriale e statale, rafforzano la sicurezza fisica e informatica dei propri uffici. Non è ancora chiaro per conto di chi l'uomo avrebbe agito."
   ],
