   "id": "z36d01b7f",
   "sez": "prima",
   "titolo": "India, i leader del movimento delle «blatte» in custodia giudiziaria nella stretta sulle proteste",
   "orig": "India news: 'Cockroach' leaders sent to judicial custody amid protest crackdown",
   "lead": "Tre leader del movimento di protesta giovanile indiano noto come «Cockroach» (le blatte) sono stati messi in custodia giudiziaria per cinque giorni, accusati di essersi introdotti in quella che fino a poco tempo prima era un'area autorizzata alla protesta. L'ondata di arresti arriva mentre migliaia di manifestanti vengono fermati a Nuova Delhi e la capitale resta sotto stretta sorveglianza. Il movimento, nato dalla contestazione alla gestione delle elezioni, si è scagliato in particolare contro il responsabile della commissione elettorale.",
   "more": [
    "La tensione politica in India è cresciuta nelle ultime settimane in vista di nuove scadenze elettorali, con proteste di piazza dell'opposizione e arresti mirati di attivisti durante i cortei. Secondo gli analisti, il movimento difficilmente riuscirà a mettere in discussione la tenuta del governo di Narendra Modi."
   ],
