   "id": "zd0e480cb",
   "sez": "prima",
   "titolo": "Usa, milioni di dollari pubblici in spot pro-Trump: agenti federali perquisiscono la casa di Ilhan Omar",
   "orig": "Government spent millions on Trump ads. And, federal agents raid Ilhan Omar's home",
   "lead": "Il governo degli Stati Uniti ha speso milioni di dollari di fondi pubblici in spot a sostegno di Donald Trump, nonostante il presidente avesse promesso che ciò non sarebbe avvenuto. Nella stessa giornata, agenti federali hanno perquisito l'abitazione della deputata democratica Ilhan Omar a Washington. I due episodi, riportati insieme da NPR, alimentano le accuse dell'opposizione su un uso improprio delle risorse pubbliche e su un clima di pressione politica verso i parlamentari critici dell'amministrazione.",
   "more": [
    "Il tema del confine tra interessi personali e incarico pubblico accompagna Trump fin dal primo mandato; l'episodio della perquisizione a Omar, una delle voci più critiche del Congresso verso la Casa Bianca, ha già suscitato reazioni da parte di altri parlamentari democratici."
   ],
