   "id": "zd4fdf6da",
   "sez": "prima",
   "titolo": "Bulgaria convoca l'ambasciatore russo dopo l'attacco di un drone che ha affondato una nave: 11 dispersi",
   "orig": "Bulgaria Summons Russian Ambassador After Drone Attack Sinks Ship, Leaving 11 Missing",
   "lead": "La Bulgaria ha convocato l'ambasciatore russo a Sofia dopo che l'attacco di un drone ha affondato una nave al largo delle sue coste, lasciando undici persone disperse. Il primo ministro Rumen Radev ha evitato di attribuire esplicitamente l'attacco a Mosca, ma ha osservato che il suo esito «avvantaggia la Federazione Russa». Nei giorni scorsi si erano già verificati episodi analoghi di attacchi a navi mercantili nel Mar Nero al largo della Bulgaria, che avevano già fatto scattare l'allerta delle autorità costiere.",
   "more": [
    "Il Mar Nero è diventato negli ultimi mesi un fronte sempre più caldo della guerra in Ucraina, con attacchi a navi e infrastrutture legate al commercio marittimo che coinvolgono anche i Paesi rivieraschi non direttamente in guerra."
   ],
