   "orig": "Google DeepMind, Google Cloud to allow European researchers access to frontier models",
   "lead": "Google DeepMind e Google Cloud hanno annunciato un programma che darà ai ricercatori universitari europei accesso ai modelli di intelligenza artificiale più avanzati del gruppo, nell'ambito di un'iniziativa pensata per sostenere la ricerca scientifica nel continente e rafforzare la collaborazione tra il settore pubblico e quello privato sull'IA. Lo riferisce CNA.",
