   "sez": "ambiente",
   "titolo": "Uganda, gli agricoltori di Kayunga spinti verso l'irrigazione solare e l'agricoltura rigenerativa",
   "orig": "Kayunga Farmers Urged to Adopt Solar Irrigation and Regenerative Agriculture",
   "lead": "Il progetto «Power for Food» promuove tra gli agricoltori del distretto ugandese di Kayunga l'irrigazione solare e tecniche di raffreddamento ed essiccazione alimentate dal sole, insieme a pratiche di agricoltura rigenerativa, per aiutarli a far fronte ai periodi di siccità, ridurre le perdite post raccolto e migliorare l'accesso ai mercati.",
   "more": [
    "L'energia solare sta diventando uno strumento sempre più diffuso nell'agricoltura dell'Africa orientale per ridurre la dipendenza dalle piogge stagionali, in un contesto di crescente variabilità climatica."
   ],
