   "sez": "ambiente",
   "titolo": "Thailandia, le alluvioni continuano a Bangkok e in altre venti province",
   "orig": "Floods persist in Bangkok and 20 provinces",
   "lead": "Il dipartimento thailandese per la prevenzione e la mitigazione dei disastri ha reso noto che le alluvioni continuano a interessare Bangkok e altre venti province, soprattutto nella pianura centrale del Paese, anche se il livello delle acque sta gradualmente calando. Le autorità restano in allerta per i prossimi giorni.",
   "more": [
    "Le piogge monsoniche provocano ogni anno allagamenti diffusi in Thailandia, in particolare nelle aree pianeggianti attraversate dal fiume Chao Phraya; le autorità gestiscono il deflusso delle acque anche per proteggere la capitale Bangkok."
   ],
