   "titolo": "Winnie the Pooh compie 100 anni: la storia dell'orsetto più amato di sempre",
   "orig": "Winnie the Pooh compie 100 anni, la storia dell'orso più amato di sempre",
   "lead": "Il 14 ottobre 1926 usciva nel Regno Unito il primo libro dedicato a Winnie the Pooh, nato dalla penna dello scrittore britannico Alan Alexander Milne. Da allora l'orsetto goloso di miele e i suoi amici del Bosco dei Cento Acri hanno attraversato un secolo, diventando un simbolo della letteratura per l'infanzia in tutto il mondo grazie anche al successo internazionale portato dagli adattamenti animati Disney. Lo riferisce Sky TG24.",
   "more": [
    "I personaggi creati da Milne, ispirati ai giocattoli di peluche del figlio Christopher Robin, restano tra i più noti della cultura pop globale e continuano a generare libri, film e merchandising a un secolo dalla loro nascita."
   ],
