   "orig": "The Superstar effect: Can Rajinikanth’s ‘Jailer 2’ collect Rs 1000 crore?",
   "lead": "Mentre il cinema tamil si prepara all'uscita di «Jailer 2», produttori e proprietari di sale discutono del richiamo al botteghino della star Rajinikanth, uno degli attori più popolari e longevi del cinema indiano. Il film, diretto da Nelson Dilipkumar con le musiche di Anirudh Ravichander, è atteso come uno dei maggiori eventi cinematografici dell'anno in India. Lo riferisce The Hindu.",
