    "La partecipazione di astronauti di Paesi europei più piccoli a missioni commerciali come quelle di SpaceX riflette la crescente diversificazione dell'accesso allo spazio, un tempo riservato quasi esclusivamente alle grandi agenzie spaziali nazionali."
