   "lead": "Lana Del Rey è tornata a esibirsi dal vivo dopo quasi un anno di assenza, scegliendo un palcoscenico insolito: il paddock del Gran Premio di Formula 1 di Singapore. Sul Padang Stage, la cantautrice statunitense ha ripercorso alcuni dei momenti più importanti della sua carriera e ha presentato dal vivo per la prima volta il brano inedito «White Feather Hawk Tail Deer Hunter».",
