   "lead": "Cosa hanno in comune l'influencer marketing, l'intelligenza artificiale e le scienze della salute? Sono tutti ambiti per cui le università statunitensi hanno lanciato negli ultimi anni nuovi corsi di laurea, nel tentativo di intercettare studenti in cerca di percorsi professionali più legati alle trasformazioni del mercato del lavoro. Lo riferisce NPR – Istruzione.",
