   "titolo": "Scoperto che il campo magnetico di Giove «ondeggia» come un disco increspato",
   "orig": "New Data from the Juno Spacecraft Reveals that Jupiter's Has a Rippling, Wavy Magnetodisk",
   "lead": "Grazie ai dati della sonda Nasa Juno, un team di scienziati ha scoperto che l'enorme campo magnetico che avvolge Giove non è piatto come si credeva, ma ondeggia come un disco increspato che ruota insieme al pianeta. Una scoperta che aiuta a capire meglio come funziona l'ambiente magnetico del più grande pianeta del Sistema solare. Lo riferisce Universe Today.",
