   "orig": "Champions League roundup: Tresoldi treble stuns Inter in Club Brugge win",
   "lead": "Il ventiduenne Nicolò Tresoldi, attaccante italo-tedesco del Club Brugge, ha firmato una tripletta che ha steso l'Inter 4-3 a San Siro, nel risultato a sorpresa della serata di Champions League. Nelle altre partite il Barcellona ha travolto 4-1 il Galatasaray, mentre il Bayern Monaco, in dieci uomini dopo l'espulsione di Olise, ha recuperato un 3-3 in casa del Viking Stavanger in Norvegia.",
