   "orig": "Turkish police raid office of opposition TV channel, the broadcaster says",
   "lead": "La polizia turca ha fatto irruzione negli uffici di Halk TV, la principale emittente televisiva vicina all'opposizione, secondo quanto riferito dalla stessa rete. Un amministratore nominato dal governo sarebbe stato incaricato di gestire il canale, nell'ultimo di una serie di episodi che le organizzazioni per la libertà di stampa considerano un ulteriore colpo al pluralismo dell'informazione in Turchia.",
