   "titolo": "Israele al voto: elezione anticipata decisiva per il futuro politico di Netanyahu",
   "orig": "Seeing pivotal election, Israelis fly from around world to vote",
   "lead": "Gli israeliani residenti all'estero stanno rientrando in massa per partecipare a un'elezione definita decisiva per il futuro del Paese, considerata un vero e proprio referendum sul primo ministro Benjamin Netanyahu e sul suo governo di destra. Con i sondaggi che indicano uno stallo tra i due schieramenti principali e la destra divisa al proprio interno, le ultime settimane di campagna elettorale si sono concentrate sulla possibile nascita di un governo di unità guidato da un candidato alternativo.",
   "more": [
    "Netanyahu guida Israele, con alcune interruzioni, dal 1996 ed è il primo ministro più longevo della storia del Paese; le sue vicende giudiziarie e le scelte politiche sulla gestione della guerra a Gaza restano al centro del dibattito elettorale."
   ],
