   "titolo": "Trump: Taiwan compra il 30% del gas naturale dal progetto del gasdotto in Alaska",
   "orig": "Trump says Taiwan agrees to buy 30% of LNG from Alaska pipeline project",
   "lead": "Il presidente statunitense Donald Trump ha annunciato che Taiwan ha accettato di acquistare il 30% del gas naturale liquefatto prodotto dal progetto del gasdotto in Alaska, un'infrastruttura strategica per l'export energetico degli Stati Uniti verso l'Asia. I termini esatti dell'accordo non sono stati resi noti. Lo riferisce The Straits Times.",
   "more": [
    "Il progetto del gasdotto in Alaska punta a esportare gas naturale liquefatto verso i mercati asiatici, offrendo a Taiwan e ad altri alleati statunitensi una fonte di approvvigionamento energetico alternativa a quelle russa e mediorientale."
   ],
