   "sez": "mondo",
   "titolo": "Usa, aboliti i 540 giorni di proroga automatica per i permessi di lavoro degli immigrati",
   "orig": "US ends 540-day grace period for immigrants after work authorisation expires",
   "lead": "Il dipartimento della Sicurezza interna degli Stati Uniti ha abolito l'estensione automatica di 540 giorni che consentiva agli immigrati di continuare a lavorare legalmente in attesa del rinnovo del permesso di lavoro scaduto. La misura, parte della più ampia stretta dell'amministrazione Trump sull'immigrazione regolare, rischia di lasciare temporaneamente senza autorizzazione al lavoro centinaia di migliaia di persone in attesa di rinnovo. Lo riferisce Times of India.",
   "more": [
    "La proroga automatica era stata introdotta per evitare interruzioni nei permessi di lavoro dovute ai ritardi burocratici nell'elaborazione delle pratiche di rinnovo, un problema cronico delle agenzie statunitensi per l'immigrazione."
   ],
