   "lead": "Il dottor Abdul Jalloh, direttore del settore salute mentale e malattie non trasmissibili del ministero della Salute della Sierra Leone, ha avvertito che ansia e fobie sono condizioni diffuse ma spesso sottovalutate, e non riguardano solo i disturbi psichiatrici più gravi. Jalloh ha invitato la popolazione a non ignorare i primi segnali di disagio psicologico e a rivolgersi ai servizi sanitari disponibili. Lo riferisce Sierraloaded.",
