  "za83ee72b": {
   "voci": [
    {
     "n": "Citizen Digital",
     "c": "Nairobi",
     "p": "XX",
     "t": "Riporta la rimozione del tumore polmonare, citando il comunicato vaticano e la dottoressa Juanita Mora sulla prognosi, con tassi di sopravvivenza 'dall'80 al 98%'. Cita le reazioni di Rubio e Albanese e testimonianze di cittadini fuori dal Gemelli.",
     "b": "a"
    },
    {
     "n": "Dawn",
     "c": "Karachi",
     "p": "XX",
     "t": "Articolo quasi identico a quello di Citizen Digital (fonte AFP), con operazione di '90 minuti', diagnosi di adenocarcinoma confermata e citazioni di Mora, Rubio, Albanese e cittadini romani.",
     "b": "a"
    },
    {
     "n": "PBS NewsHour",
     "c": "Arlington",
     "p": "US",
     "t": "Intervista il radiologo Omer Awan, che spiega la natura dell'adenocarcinoma, definisce il nodulo localizzato un segnale 'positivo' e descrive i tempi di recupero, da settimane a mesi, senza citare fonti vaticane dirette.",
     "b": "a"
    },
    {
     "n": "Il Messaggero",
     "c": "Roma",
     "p": "IT",
     "t": "Si concentra sul bollettino medico ufficiale dei dottori Carbone e Margaritora e sulle dichiarazioni del professor Facciolo, che parla di 'diagnosi tempestiva' e spiega che serviranno l'esame istologico definitivo e la valutazione dei linfonodi per decidere eventuali terapie.",
     "b": "a"
    },
    {
     "n": "Citizen Digital",
     "c": "Nairobi",
     "p": "XX",
     "t": "In un secondo pezzo approfondisce il parere di più esperti (Mora, Spigel, Carbone) sui tipi di cancro al polmone, sottolineando che l'intervento diretto senza terapie preventive è un segnale di stadio precoce e buona prognosi.",
     "b": "a"
    },
    {
     "n": "NPR",
     "c": "Washington",
     "p": "US",
     "t": "Riporta la diagnosi di adenocarcinoma e aggiunge dettagli biografici: il Papa fa sport, gioca a tennis e va a cavallo; segnala inoltre che il fratello Louis è ricoverato per un cancro e che la madre ne morì nel 1990.",
     "b": "a"
    }
   ],
   "divergono": "Il Messaggero è l'unica testata a riportare per intero il bollettino medico italiano con nomi dell'équipe chirurgica e il parere di esperti italiani (Facciolo, Mercadante) sulle fasi successive. NPR aggiunge un elemento assente altrove: la storia familiare di cancro (fratello ricoverato, madre deceduta nel 1990) e dettagli sullo stile di vita sportivo del Papa. PBS si concentra sull'aspetto clinico generale tramite un esperto esterno, senza riportare le reazioni politiche citate invece da Citizen Digital e Dawn (Rubio, Albanese). Le cifre sulla sopravvivenza a cinque anni variano leggermente tra le fonti (63-67% se localizzato, 80-98% se operato precocemente, secondo Citizen Digital)."
  },
